var a=`0217-crema-catalana`;var i=`world-0217`;var n=`ES`;var r=`southern-europe`;var o=4;var s=18;var l={en:`Crema Catalana`,ua:`Каталонський крем`};var h={en:`A traditional Spain dish made with whole cow milk, lemon zest, egg yolk, cornstarch. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Іспанія. Основні інгредієнти: цільне коров'яче молоко, цедра лимона, яєчний жовток, кукурудзяний крохмаль. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var m=[{en:`Add the listed ingredients to the pot. Keep at a gentle simmer for about 8 minutes, until tender and cooked through.`,ua:`Додайте зазначені складники до каструлі. Варіть за слабкого кипіння приблизно 8 хвилин до м’якості та готовності.`,t:[`simmering`],m:8,i:[[`whole-cow-milk`,500,`ml`],[`ceylon-cinnamon`,1,`pcs`],[`lemon-zest`,7,`g`]]},{en:`Temper the yolks and starch mixture with hot aromatic milk, return to the saucepan and stir over gentle heat until thickened. Pour into shallow ramekins and chill.`,ua:`Темперуйте жовтки з крохмалем гарячим ароматним молоком, поверніть у сотейник та помішуйте на малому вогні до загустіння. Розлийте у формочки й охолодіть.`,t:[`creaming-butter-sugar`,`whisking`],m:7,i:[[`egg-yolk`,5,`pcs`],[`white-granulated-sugar`,110,`g`],[`cornstarch`,35,`g`]]},{en:`Just before serving, sprinkle thinly with sugar and caramelize it using a kitchen torch or hot salamander to form a brittle crust.`,ua:`Перед подачею присипте тонким шаром цукру та карамелізуйте кухонним пальником або верхнім жаром до хрусткої скоринки.`,t:[`caramelizing-sugar`],m:3,i:[[`brown-sugar`,45,`g`]]}];var u={slug:a,id:i,country:`ES`,region:r,servings:4,minutes:18,title:l,text:h,steps:m};export{n as country,u as default,i as id,s as minutes,r as region,o as servings,a as slug,m as steps,h as text,l as title};